import{_ as s,c as t,o as n,j as e,a as r}from"./chunks/framework.BKeRpnBD.js";const _=JSON.parse('{"title":"爻数第十三","description":"杭氏易学 - 爻数第十三","frontmatter":{"title":"爻数第十三","description":"杭氏易学 - 爻数第十三"},"headers":[],"relativePath":"zh/classics/hangshi/014.md","filePath":"zh/classics/hangshi/014.md"}'),i={name:"zh/classics/hangshi/014.md"};function l(c,a,o,d,h,p){return n(),t("div",null,[...a[0]||(a[0]=[e("h1",{id:"爻数第十三",tabindex:"-1"},[r("爻数第十三 "),e("a",{class:"header-anchor",href:"#爻数第十三","aria-label":"Permalink to “爻数第十三”"},"​")],-1),e("p",null,"六位成章，阴阳迭运。位虚爻实，奇偶相生。积爻成卦，数亦相因。复一坎子，震未出用，故曰“复小”。临二丑寅，坤兑数十，故曰“临大”。阴爻无始，阳爻无终。阴阳首尾，往复不穷。故数尽十位，而爻十二。天五地六，以定甲子。八宫六世，三四相重。飞伏隐见，变化无尽，而无不可以数稽之。故爻位与象义既明，必征之于数，而后是非可辨也。",-1),e("p",null,"阴阳六爻，皆指乾坤。乾父坤母，六子卦皆分乾坤之爻，各得乾坤之一体。象数变化，皆不离其宗。郑氏爻辰，即以乾坤两卦，分十二辰。钟度声律，亦各以此数交错，相生相合，而各得其应得之数。《节?彖传》曰：“节以制度。君子以制度数，议德行。”若由后儒之说，德行与度数何涉？宋人性理诸书，汗牛充栋，所谓表里精粗无不到者，独无度数以节之。阴阳五行，皆凿空之谈。而所谓异端者，若老子若墨子若庄列诸子，及释家大乘经典，其言之精者，各有数度，各有法象之可征。皆所谓法言，非任意空谈可拟也。故明乎八卦之象数，明乎《彖》、《象》十翼无一辞一字之不合象数，而后三代两汉文章之度数可辨。后世之书是否合于度数者，亦皆可辨矣 【扬子云知《易》象数理之精，恐后人不解，乃苦心焦思作《太玄》，以明数。作《法言》，以仿《论语》。非拟经侮圣也，其意欲人之由浅入深，因《太玄》而进于《易》。因《法言》而悟《论语》之法度，用心良苦。乃后人并《太玄》不能解，何有于《易》？读《论语注疏》，更蔑视《法言》。又以朱子纲目“莽大夫”三字作扬雄定评，后世遂存以人废言之成见。《太玄》、《法言》乃真成覆酱瓶之物。《太玄》、《法言》不足惜，《易经》、《论语》法象数度之不明，贻人心世道之优，良足痛焉！】 。",-1),e("p",null,"乾简坤易，象数著明。象由微而知著，数执简以御繁。太极由是生两仪，生四象，生八卦，以生六十四卦。而六十四卦仍以一“是 【《未济?上六?象》曰“有孚失是”，为全经最后之一字。】 ”返本还原。故欲求其“是”，当求诸始。乾坤《易》之始，六爻乾坤之始，一画开天又六爻之始。故言卦数者，必自爻数始。",-1)])])}const f=s(i,[["render",l]]);export{_ as __pageData,f as default};
